import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.BbSdnUwJ.js";const u=JSON.parse('{"title":"Vocabulary","description":"","frontmatter":{},"headers":[],"relativePath":"reference/vocabulary.md","filePath":"reference/vocabulary.md"}'),r={name:"reference/vocabulary.md"};function c(h,t,n,i,s,l){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="vocabulary" tabindex="-1">Vocabulary <a class="header-anchor" href="#vocabulary" aria-label="Permalink to &quot;Vocabulary&quot;">​</a></h1><p>This page is generated from <code>mobiledsl.semantic.model.vocabulary</code>; edit the code, not the page. It lists every name a program may use beyond the grammar&#39;s keywords, and what each takes. Numbers carry no unit: the parameter name carries it by suffix (<code>_s</code> seconds, <code>_m</code> metres, <code>_rad</code> radians, <code>_mps</code> metres per second).</p><h2 id="component-types-core" tabindex="-1">Component types (<code>.core</code>) <a class="header-anchor" href="#component-types-core" aria-label="Permalink to &quot;Component types (`.core`)&quot;">​</a></h2><p>A component type is the kind of part a program places. A part can be used as a type when its library entry lists the type under <code>profiles</code>; the type&#39;s category is the kind of physical thing the part must be, which decides what its entry declares (a wheel its radius, a chassis its connectors). The chassis takes only <code>ref</code>; every other component is placed by <code>glue</code>. A type exists only when the compiler acts on it: a chassis type has kinematics, a wheel type a contact model, a sensor type a simulated sensor and a use for its data. Everything the compiler merely carries is an <code>Attachment</code>; the library entry says what the part is.</p><table tabindex="0"><thead><tr><th>Type</th><th>Category</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Mecanum_four_wheel</code></td><td>chassis</td><td>Four mecanum wheels; holonomic.</td></tr><tr><td><code>Diff_drive</code></td><td>chassis</td><td>Four driven standard wheels, skid steer.</td></tr><tr><td><code>Diff_two_caster</code></td><td>chassis</td><td>Two driven standard wheels and a caster.</td></tr><tr><td><code>Tricycle</code></td><td>chassis</td><td>One steered, driven front wheel and two free rear wheels.</td></tr><tr><td><code>Ackermann</code></td><td>chassis</td><td>Two steered front wheels, two driven rear wheels.</td></tr><tr><td><code>Omni_drive</code></td><td>chassis</td><td>Four omni wheels; holonomic.</td></tr><tr><td><code>Omni_three_wheel</code></td><td>chassis</td><td>Three omni wheels on a circle; holonomic.</td></tr><tr><td><code>Mecanum</code></td><td>wheel</td><td>A mecanum wheel.</td></tr><tr><td><code>Standard</code></td><td>wheel</td><td>A plain driven wheel.</td></tr><tr><td><code>Caster</code></td><td>wheel</td><td>A passive support wheel.</td></tr><tr><td><code>Omni_wheel</code></td><td>wheel</td><td>An omni wheel.</td></tr><tr><td><code>Lidar</code></td><td>sensor</td><td>A planar laser scanner.</td></tr><tr><td><code>Lidar3D</code></td><td>sensor</td><td>A spinning multi-ring laser; its cloud marks obstacles and its middle ring can stand in for a planar laser.</td></tr><tr><td><code>Camera</code></td><td>sensor</td><td>An RGB camera.</td></tr><tr><td><code>DepthCamera</code></td><td>sensor</td><td>A depth camera; its cloud can stand in for a laser.</td></tr><tr><td><code>RGBD</code></td><td>sensor</td><td>A colour camera with a registered depth image; its cloud can stand in for a laser.</td></tr><tr><td><code>IMU</code></td><td>sensor</td><td>An inertial measurement unit.</td></tr><tr><td><code>Ultrasonic</code></td><td>sensor</td><td>A range finder with a narrow cone; its reading marks the costmaps&#39; range layer.</td></tr><tr><td><code>Bumper</code></td><td>sensor</td><td>A contact switch on the body; Check_contact on it reads what pressed it.</td></tr><tr><td><code>Attachment</code></td><td>attachment</td><td>A part the compiler carries but does not act on: an arm, a gripper, a tray. It adds mass and shape; the library entry says what it is.</td></tr></tbody></table><p>Parameters of a chassis:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>ref</code></td><td>string</td><td>yes</td><td>The library part id.</td></tr></tbody></table><p>Parameters of a wheel, sensor, or attachment:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>ref</code></td><td>string</td><td>yes</td><td>The library part id.</td></tr><tr><td><code>glue</code></td><td>tuple of 6 or 7</td><td>yes</td><td>Where the part mates on the chassis: <code>(x, y, z, nx, ny, nz)</code> or with a roll angle <code>(x, y, z, nx, ny, nz, roll)</code>. The point and the unit normal are in the chassis frame; the part&#39;s connector is aligned to them.</td></tr></tbody></table><h3 id="chassis-types" tabindex="-1">Chassis types <a class="header-anchor" href="#chassis-types" aria-label="Permalink to &quot;Chassis types&quot;">​</a></h3><p>What each chassis type needs and what the assembled base can do. A program places one wheel of an allowed type on each wheel mount; the wheel&#39;s <code>glue</code> must equal the chassis connector that the part&#39;s profile maps the mount to. A <code>Caster</code> wheel is passive and may sit on any other connector. Every mount is driven unless the table lists the driven ones; a mount that steers turns about the kingpin the chassis part declares on that connector.</p><table tabindex="0"><thead><tr><th>Chassis</th><th>Wheel mounts</th><th>Wheel type</th><th>Driven</th><th>Steered</th><th>Holonomic</th><th>Spins in place</th></tr></thead><tbody><tr><td><code>Mecanum_four_wheel</code></td><td><code>front_left_wheel</code>, <code>front_right_wheel</code>, <code>rear_left_wheel</code>, <code>rear_right_wheel</code></td><td><code>Mecanum</code></td><td>all</td><td>none</td><td>yes</td><td>yes</td></tr><tr><td><code>Diff_drive</code></td><td><code>front_left_wheel</code>, <code>front_right_wheel</code>, <code>rear_left_wheel</code>, <code>rear_right_wheel</code></td><td><code>Standard</code></td><td>all</td><td>none</td><td>no</td><td>yes</td></tr><tr><td><code>Diff_two_caster</code></td><td><code>left_wheel</code>, <code>right_wheel</code></td><td><code>Standard</code></td><td>all</td><td>none</td><td>no</td><td>yes</td></tr><tr><td><code>Tricycle</code></td><td><code>front_wheel</code>, <code>rear_left_wheel</code>, <code>rear_right_wheel</code></td><td><code>Standard</code></td><td><code>front_wheel</code></td><td><code>front_wheel</code></td><td>no</td><td>no</td></tr><tr><td><code>Ackermann</code></td><td><code>front_left_wheel</code>, <code>front_right_wheel</code>, <code>rear_left_wheel</code>, <code>rear_right_wheel</code></td><td><code>Standard</code></td><td><code>rear_left_wheel</code>, <code>rear_right_wheel</code></td><td><code>front_left_wheel</code>, <code>front_right_wheel</code></td><td>no</td><td>no</td></tr><tr><td><code>Omni_drive</code></td><td><code>front_left_wheel</code>, <code>front_right_wheel</code>, <code>rear_left_wheel</code>, <code>rear_right_wheel</code></td><td><code>Omni_wheel</code></td><td>all</td><td>none</td><td>yes</td><td>yes</td></tr><tr><td><code>Omni_three_wheel</code></td><td><code>front_wheel</code>, <code>rear_left_wheel</code>, <code>rear_right_wheel</code></td><td><code>Omni_wheel</code></td><td>all</td><td>none</td><td>yes</td><td>yes</td></tr></tbody></table><h2 id="world-world" tabindex="-1">World (<code>.world</code>) <a class="header-anchor" href="#world-world" aria-label="Permalink to &quot;World (`.world`)&quot;">​</a></h2><h3 id="entity-types" tabindex="-1">Entity types <a class="header-anchor" href="#entity-types" aria-label="Permalink to &quot;Entity types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Obstacle</code></td><td>Something the robot must not touch: touching it fails the run.</td></tr><tr><td><code>SupportSurface</code></td><td>A floor, ramp or pad the robot drives on; contact is expected.</td></tr><tr><td><code>Marker</code></td><td>A visual mark such as a line or a goal disc; no collision by default.</td></tr></tbody></table><p>All entity types take the same parameters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>box</code>, <code>sphere</code>, <code>cylinder</code></td><td>no</td><td>A primitive shape; exactly one of <code>type</code> and <code>ref</code>.</td></tr><tr><td><code>ref</code></td><td>string</td><td>no</td><td>A scene asset in a library; exactly one of <code>type</code> and <code>ref</code>.</td></tr><tr><td><code>pos</code></td><td>tuple of 7</td><td>yes</td><td>World pose <code>(x, y, z, qx, qy, qz, qw)</code>; no rotation is <code>(x, y, z, 0, 0, 0, 1)</code>.</td></tr><tr><td><code>size</code></td><td>tuple of 3</td><td>no</td><td>Primitive dimensions <code>(x, y, z)</code> in metres; required with <code>type</code>.</td></tr><tr><td><code>is_static</code></td><td>bool</td><td>no</td><td>Fixed in place (default <code>true</code>). No target moves an entity: it states no mass to move it with, so <code>false</code> is refused.</td></tr><tr><td><code>collision</code></td><td>bool</td><td>no</td><td>Emits collision geometry (default depends on the type).</td></tr></tbody></table><h3 id="scenario" tabindex="-1"><code>Scenario</code> <a class="header-anchor" href="#scenario" aria-label="Permalink to &quot;`Scenario`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>ref</code></td><td>string</td><td>yes</td><td>The base environment; <code>empty</code> for none.</td></tr><tr><td><code>ground_plane</code></td><td>bool</td><td>no</td><td>Add a ground plane (default <code>false</code>).</td></tr></tbody></table><h3 id="goal" tabindex="-1"><code>Goal</code> <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;`Goal`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>pose</code></td><td>tuple of 7</td><td>no</td><td>The goal pose <code>(x, y, z, qx, qy, qz, qw)</code>; one of <code>pose</code> and <code>target</code>.</td></tr><tr><td><code>target</code></td><td><code>@world/&lt;entity&gt;</code></td><td>no</td><td>An entity whose pose is the goal; one of <code>pose</code> and <code>target</code>.</td></tr></tbody></table><h3 id="physics" tabindex="-1"><code>physics</code> <a class="header-anchor" href="#physics" aria-label="Permalink to &quot;`physics`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>gravity</code></td><td>tuple of 3</td><td>no</td><td>Gravity <code>(x, y, z)</code> in m/s^2.</td></tr></tbody></table><h3 id="spawn" tabindex="-1"><code>spawn</code> <a class="header-anchor" href="#spawn" aria-label="Permalink to &quot;`spawn`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>robot</code></td><td><code>@core/&lt;robot&gt;</code></td><td>yes</td><td>The robot declared in the <code>.core</code> file.</td></tr><tr><td><code>pose</code></td><td>tuple of 7</td><td>yes</td><td>Where the robot starts, <code>(x, y, z, qx, qy, qz, qw)</code>.</td></tr></tbody></table><h2 id="task-task" tabindex="-1">Task (<code>.task</code>) <a class="header-anchor" href="#task-task" aria-label="Permalink to &quot;Task (`.task`)&quot;">​</a></h2><h3 id="task" tabindex="-1"><code>Task</code> <a class="header-anchor" href="#task" aria-label="Permalink to &quot;`Task`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>timeout_s</code></td><td>number</td><td>no</td><td>The whole task must finish within this many seconds.</td></tr></tbody></table><h3 id="composites-take-children" tabindex="-1">Composites (take children) <a class="header-anchor" href="#composites-take-children" aria-label="Permalink to &quot;Composites (take children)&quot;">​</a></h3><h4 id="sequence" tabindex="-1"><code>Sequence</code> <a class="header-anchor" href="#sequence" aria-label="Permalink to &quot;`Sequence`&quot;">​</a></h4><p>Run children in order; stop at the first failure.</p><p>No parameters.</p><h4 id="fallback" tabindex="-1"><code>Fallback</code> <a class="header-anchor" href="#fallback" aria-label="Permalink to &quot;`Fallback`&quot;">​</a></h4><p>Run children in order; stop at the first success.</p><p>No parameters.</p><h4 id="parallel" tabindex="-1"><code>Parallel</code> <a class="header-anchor" href="#parallel" aria-label="Permalink to &quot;`Parallel`&quot;">​</a></h4><p>Run children together.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>policy</code></td><td><code>success_on_all</code>, <code>success_on_one</code></td><td>yes</td><td>When the parallel succeeds.</td></tr></tbody></table><h3 id="decorators-take-exactly-one-child" tabindex="-1">Decorators (take exactly one child) <a class="header-anchor" href="#decorators-take-exactly-one-child" aria-label="Permalink to &quot;Decorators (take exactly one child)&quot;">​</a></h3><h4 id="retry" tabindex="-1"><code>Retry</code> <a class="header-anchor" href="#retry" aria-label="Permalink to &quot;`Retry`&quot;">​</a></h4><p>Re-run the child until it succeeds, at most <code>count</code> times.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>count</code></td><td>number</td><td>yes</td><td>Number of attempts.</td></tr></tbody></table><h4 id="repeat" tabindex="-1"><code>Repeat</code> <a class="header-anchor" href="#repeat" aria-label="Permalink to &quot;`Repeat`&quot;">​</a></h4><p>Run the child <code>count</code> times.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>count</code></td><td>number</td><td>yes</td><td>Number of attempts.</td></tr></tbody></table><h4 id="timeout" tabindex="-1"><code>Timeout</code> <a class="header-anchor" href="#timeout" aria-label="Permalink to &quot;`Timeout`&quot;">​</a></h4><p>Fail the child if it runs longer than <code>timeout_s</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>timeout_s</code></td><td>number</td><td>yes</td><td>Seconds.</td></tr></tbody></table><h4 id="inverter" tabindex="-1"><code>Inverter</code> <a class="header-anchor" href="#inverter" aria-label="Permalink to &quot;`Inverter`&quot;">​</a></h4><p>Swap the child&#39;s success and failure.</p><p>No parameters.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><h4 id="navigate" tabindex="-1"><code>Navigate</code> <a class="header-anchor" href="#navigate" aria-label="Permalink to &quot;`Navigate`&quot;">​</a></h4><p>Drive to a goal, avoiding obstacles.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>goal</code></td><td><code>@world/&lt;goal or entity&gt;</code></td><td>yes</td><td>A goal or an entity in the world.</td></tr></tbody></table><h4 id="wait" tabindex="-1"><code>Wait</code> <a class="header-anchor" href="#wait" aria-label="Permalink to &quot;`Wait`&quot;">​</a></h4><p>Do nothing for a while.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>duration_s</code></td><td>number</td><td>yes</td><td>Seconds.</td></tr></tbody></table><h4 id="stop" tabindex="-1"><code>Stop</code> <a class="header-anchor" href="#stop" aria-label="Permalink to &quot;`Stop`&quot;">​</a></h4><p>Come to rest.</p><p>No parameters.</p><h4 id="spin" tabindex="-1"><code>Spin</code> <a class="header-anchor" href="#spin" aria-label="Permalink to &quot;`Spin`&quot;">​</a></h4><p>Turn in place.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>angle_rad</code></td><td>number</td><td>yes</td><td>Signed angle in radians.</td></tr></tbody></table><h4 id="advance" tabindex="-1"><code>Advance</code> <a class="header-anchor" href="#advance" aria-label="Permalink to &quot;`Advance`&quot;">​</a></h4><p>Drive straight ahead.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>distance_m</code></td><td>number</td><td>yes</td><td>Distance in metres.</td></tr><tr><td><code>speed_mps</code></td><td>number</td><td>no</td><td>Speed in m/s.</td></tr></tbody></table><h4 id="backup" tabindex="-1"><code>BackUp</code> <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;`BackUp`&quot;">​</a></h4><p>Drive straight back.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>distance_m</code></td><td>number</td><td>yes</td><td>Distance in metres.</td></tr><tr><td><code>speed_mps</code></td><td>number</td><td>no</td><td>Speed in m/s.</td></tr></tbody></table><h4 id="strafe" tabindex="-1"><code>Strafe</code> <a class="header-anchor" href="#strafe" aria-label="Permalink to &quot;`Strafe`&quot;">​</a></h4><p>Drive sideways; needs a holonomic base.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>distance_m</code></td><td>number</td><td>yes</td><td>Signed distance in metres; positive is left.</td></tr><tr><td><code>speed_mps</code></td><td>number</td><td>no</td><td>Speed in m/s.</td></tr></tbody></table><h3 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;Conditions&quot;">​</a></h3><h4 id="goalreached" tabindex="-1"><code>GoalReached</code> <a class="header-anchor" href="#goalreached" aria-label="Permalink to &quot;`GoalReached`&quot;">​</a></h4><p>True when the robot is at the goal.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>goal</code></td><td><code>@world/&lt;goal or entity&gt;</code></td><td>yes</td><td>A goal or an entity in the world.</td></tr></tbody></table><h4 id="distancetraveled" tabindex="-1"><code>DistanceTraveled</code> <a class="header-anchor" href="#distancetraveled" aria-label="Permalink to &quot;`DistanceTraveled`&quot;">​</a></h4><p>True once the robot has moved this far.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>distance_m</code></td><td>number</td><td>yes</td><td>Distance in metres.</td></tr></tbody></table><h4 id="timeexpired" tabindex="-1"><code>TimeExpired</code> <a class="header-anchor" href="#timeexpired" aria-label="Permalink to &quot;`TimeExpired`&quot;">​</a></h4><p>True once this much time has passed.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>duration_s</code></td><td>number</td><td>yes</td><td>Seconds.</td></tr></tbody></table><h2 id="evaluate-eval" tabindex="-1">Evaluate (<code>.eval</code>) <a class="header-anchor" href="#evaluate-eval" aria-label="Permalink to &quot;Evaluate (`.eval`)&quot;">​</a></h2><h3 id="check-vel" tabindex="-1"><code>Check_vel</code> <a class="header-anchor" href="#check-vel" aria-label="Permalink to &quot;`Check_vel`&quot;">​</a></h3><p>Joint speed in rad/s: the magnitude of every sample stays within the bounds.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>target</code></td><td><code>@core/&lt;component&gt;</code></td><td>yes</td><td>The wheel or joint to observe.</td></tr><tr><td><code>min</code></td><td>number</td><td>no</td><td>Lower bound; at least one bound is required.</td></tr><tr><td><code>max</code></td><td>number</td><td>no</td><td>Upper bound; at least one bound is required.</td></tr></tbody></table><h3 id="check-acc" tabindex="-1"><code>Check_acc</code> <a class="header-anchor" href="#check-acc" aria-label="Permalink to &quot;`Check_acc`&quot;">​</a></h3><p>Joint acceleration in rad/s^2, the difference of successive speed samples; every sample stays within the bounds.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>target</code></td><td><code>@core/&lt;component&gt;</code></td><td>yes</td><td>The wheel or joint to observe.</td></tr><tr><td><code>min</code></td><td>number</td><td>no</td><td>Lower bound; at least one bound is required.</td></tr><tr><td><code>max</code></td><td>number</td><td>no</td><td>Upper bound; at least one bound is required.</td></tr></tbody></table><h3 id="check-jerk" tabindex="-1"><code>Check_jerk</code> <a class="header-anchor" href="#check-jerk" aria-label="Permalink to &quot;`Check_jerk`&quot;">​</a></h3><p>Joint jerk in rad/s^3, the second difference of the speed samples; every sample stays within the bounds.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>target</code></td><td><code>@core/&lt;component&gt;</code></td><td>yes</td><td>The wheel or joint to observe.</td></tr><tr><td><code>min</code></td><td>number</td><td>no</td><td>Lower bound; at least one bound is required.</td></tr><tr><td><code>max</code></td><td>number</td><td>no</td><td>Upper bound; at least one bound is required.</td></tr></tbody></table><h3 id="check-effort" tabindex="-1"><code>Check_effort</code> <a class="header-anchor" href="#check-effort" aria-label="Permalink to &quot;`Check_effort`&quot;">​</a></h3><p>Joint effort in N*m: the magnitude of every sample stays within the bounds.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>target</code></td><td><code>@core/&lt;component&gt;</code></td><td>yes</td><td>The wheel or joint to observe.</td></tr><tr><td><code>min</code></td><td>number</td><td>no</td><td>Lower bound; at least one bound is required.</td></tr><tr><td><code>max</code></td><td>number</td><td>no</td><td>Upper bound; at least one bound is required.</td></tr></tbody></table><h3 id="check-distance" tabindex="-1"><code>Check_distance</code> <a class="header-anchor" href="#check-distance" aria-label="Permalink to &quot;`Check_distance`&quot;">​</a></h3><p>Distance in metres from the robot (or <code>source</code>) to <code>target</code>: <code>min</code> bounds the closest approach over the run, <code>max</code> the distance when the task ends.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>target</code></td><td><code>@world/&lt;goal or entity&gt;</code></td><td>yes</td><td>The entity or goal measured to.</td></tr><tr><td><code>source</code></td><td><code>@core/&lt;component&gt;</code></td><td>no</td><td>The robot part measured from.</td></tr><tr><td><code>min</code></td><td>number</td><td>no</td><td>Lower bound; at least one bound is required.</td></tr><tr><td><code>max</code></td><td>number</td><td>no</td><td>Upper bound; at least one bound is required.</td></tr></tbody></table><h3 id="check-clearance" tabindex="-1"><code>Check_clearance</code> <a class="header-anchor" href="#check-clearance" aria-label="Permalink to &quot;`Check_clearance`&quot;">​</a></h3><p>Distance in metres from the robot (or <code>source</code>) to the nearest obstacle, at its closest over the run.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>target</code></td><td><code>@world/&lt;goal or entity&gt;</code></td><td>no</td><td>The obstacle to measure to; every obstacle when absent or not an obstacle.</td></tr><tr><td><code>source</code></td><td><code>@core/&lt;component&gt;</code></td><td>no</td><td>The robot part measured from.</td></tr><tr><td><code>min</code></td><td>number</td><td>no</td><td>Lower bound; at least one bound is required.</td></tr><tr><td><code>max</code></td><td>number</td><td>no</td><td>Upper bound; at least one bound is required.</td></tr></tbody></table><h3 id="check-contact" tabindex="-1"><code>Check_contact</code> <a class="header-anchor" href="#check-contact" aria-label="Permalink to &quot;`Check_contact`&quot;">​</a></h3><p>Seconds the robot part <code>target</code> spends touching a scene entity: what its contact switch reports when it is a Bumper, else the simulator&#39;s geometry.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>target</code></td><td><code>@core/&lt;component&gt;</code></td><td>yes</td><td>The robot part.</td></tr><tr><td><code>source</code></td><td><code>@core/&lt;component&gt;</code></td><td>no</td><td>The robot part measured from.</td></tr><tr><td><code>min</code></td><td>number</td><td>no</td><td>Lower bound; at least one bound is required.</td></tr><tr><td><code>max</code></td><td>number</td><td>no</td><td>Upper bound; at least one bound is required.</td></tr></tbody></table><h3 id="check-time" tabindex="-1"><code>Check_time</code> <a class="header-anchor" href="#check-time" aria-label="Permalink to &quot;`Check_time`&quot;">​</a></h3><p>Duration of the task in seconds, from its first tick to its last.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>target</code></td><td><code>@task/&lt;task&gt;</code></td><td>yes</td><td>The task.</td></tr><tr><td><code>min</code></td><td>number</td><td>no</td><td>Lower bound; at least one bound is required.</td></tr><tr><td><code>max</code></td><td>number</td><td>no</td><td>Upper bound; at least one bound is required.</td></tr></tbody></table>',108)])])}const p=e(r,[["render",c]]);export{u as __pageData,p as default};
